-- Language: zh_Hans_CN
insert or replace into LocalizedText
    (Language,      Tag,                                                             Text)
values
    ("zh_Hans_CN",  "LOC_GAMEMODE_MONOPOLIES_NAME",                                  "行业与公司模式"),
    ("zh_Hans_CN",  "LOC_GAMEMODE_MONOPOLIES_DESCRIPTION",                           "[COLOR_Civ6LightBlue]欢迎来到“和而不同”行业与公司模式，我们对行业、公司、产品的效果进行了全面的重制，请查阅内置百科了解详情。[ENDCOLOR][NEWLINE]控制、改良您的奢侈品资源，并在此之上进行拓展！在“行业与公司”模式中，您可以围绕奢侈品资源建立利润丰硕的行业、创建公司进行深度开发，并生产特色产品，确立您在商业历史中的显著地位。"),
    ("zh_Hans_CN",  "LOC_IMPROVEMENT_CHATEAU_DESCRIPTION_MONOPOLIES",                "解锁建造者建造法国特色改良城堡庄园的能力。[NEWLINE][NEWLINE]+2 [ICON_FOOD] 食物、+1 [ICON_Culture] 文化值、+1 [ICON_HOUSING] 住房。每相邻1个加成资源+1 [ICON_FOOD] 食物，每相邻1个奢侈资源或奇观+2 [ICON_Culture] 文化值。额外提供一份相邻的且已改良的种植园、农场或伐木场奢侈资源。获得每种与城堡庄园相邻且已改良的种植园、农场或伐木场奢侈资源的对应行业效果。为相邻单元格+1魅力。每个城市仅限建造一座，且必须建在加成或奢侈品资源旁。");